import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import { addagenceEtAdminClient } from "../../services/ApiAgence"; 

export default function CardAddAgence() {
  const history = useHistory();
  const [newAgence, setNewAgence] = useState({
    Nom: "",
    ville: "",
    codePostal: "",
    local: "",
    adminNom: "",
    adminPrenom: "",
    adminEmail: "",
    adminPassword: ""
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewAgence({ ...newAgence, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    let formErrors = {};
    if (!newAgence.Nom.trim()) formErrors.Nom = "Nom requis";
    if (!newAgence.ville.trim()) formErrors.ville = "Ville requise";
    if (!newAgence.codePostal.trim()) formErrors.codePostal = "Code postal requis";
    if (!newAgence.local.trim()) formErrors.local = "Local requis";
    if (!newAgence.adminNom.trim()) formErrors.adminNom = "Nom admin requis";
    if (!newAgence.adminPrenom.trim()) formErrors.adminPrenom = "Prénom admin requis";
    if (!newAgence.adminEmail.trim()) formErrors.adminEmail = "Email admin requis";
    if (!newAgence.adminPassword.trim()) formErrors.adminPassword = "Mot de passe admin requis";

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    try {
      await addagenceEtAdminClient(newAgence);
      history.push("/admin/Agence");
    } catch (error) {
      console.error("Erreur lors de l'ajout :", error);
      alert("Erreur lors de l'ajout de l'agence et de l'admin client.");
    }
  };

  return (
    <div className="relative flex flex-col w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Ajouter une agence + admin</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow"
            onClick={() => history.push("/admin/agences")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Informations Agence</h6>
          <div className="flex flex-wrap">
            {/* Champs Agence */}
            {["Nom", "ville", "codePostal", "local"].map((field, i) => (
              <div key={i} className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                    {field}
                  </label>
                  <input
                    type="text"
                    name={field}
                    value={newAgence[field]}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors[field] ? "border border-red-500" : ""}`}
                    placeholder={field}
                  />
                  {errors[field] && (
                    <p className="text-red-500 text-xs italic mt-1">{errors[field]}</p>
                  )}
                </div>
              </div>
            ))}
          </div>

          <h6 className="text-blueGray-400 text-sm mt-6 mb-6 font-bold uppercase">Admin Client</h6>
          <div className="flex flex-wrap">
            {/* Champs Admin */}
            {[
              { label: "Nom", name: "adminNom" },
              { label: "Prénom", name: "adminPrenom" },
              { label: "Email", name: "adminEmail", type: "email" },
              { label: "Mot de passe", name: "adminPassword", type: "password" },
            ].map(({ label, name, type = "text" }, i) => (
              <div key={i} className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                    {label}
                  </label>
                  <input
                    type={type}
                    name={name}
                    value={newAgence[name]}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors[name] ? "border border-red-500" : ""}`}
                    placeholder={label}
                  />
                  {errors[name] && (
                    <p className="text-red-500 text-xs italic mt-1">{errors[name]}</p>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md"
            >
              Enregistrer
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
